const std::size_t num_rays = static_cast<std::size_t>(numberOfChecks);
const std::size_t dim = 3;
const double eps = std::numeric_limits<double>::epsilon() * 100.0;

std::vector<Point3d> rays;
for (std::size_t i = 0; i < num_rays; ++i) {
    // Generate random direction vectors (avoid zero vector)
    Point3d dir;
    do {
        dir = Point3d(
            (std::rand() / static_cast<double>(RAND_MAX)) * 2.0 - 1.0,
            (std::rand() / static_cast<double>(RAND_MAX)) * 2.0 - 1.0,
            (std::rand() / static_cast<double>(RAND_MAX)) * 2.0 - 1.0
        );
    } while (dir.x() == 0.0 && dir.y() == 0.0 && dir.z() == 0.0);

    rays.push_back(dir);
}

std::size_t inside_count = 0;
for (const auto& dir : rays) {
    Ray_3 ray(p, dir);
    std::vector<Point3d> intersection_points;

    // Collect all intersections with the mesh
    CGAL::copy(
        CGAL::intersection_and_append(
            tree,
            ray,
            std::back_inserter(intersection_points)
        ),
        std::back_inserter(intersection_points)
    );

    // Sort intersections by distance from origin
    std::sort(
        intersection_points.begin(),
        intersection_points.end(),
        [&ray](const Point3d& a, const Point3d& b) {
            return CGAL::squared_distance(ray.source(), a) < CGAL::squared_distance(ray.source(), b);
        }
    );

    // Count intersections (odd = inside)
    std::size_t count = 0;
    for (const auto& pt : intersection_points) {
        if (CGAL::squared_distance(ray.source(), pt) > eps) {
            ++count;
        }
    }

    if (count % 2 == 1) {
        ++inside_count;
    }
}

// If more than half of the rays intersect an odd number of times, consider inside
return inside_count > (num_rays / 2);
// END_CODE

